ROE = {
    "window": ("2026-11-02", "2026-12-18"),
    "prohibited": {"denial_of_service", "delete_user_data", "real_ransomware"},
    "off_limits": {"payroll-db-01", "icu-monitor-net"},
    "halted": False,   # set True by the control group: everything stops
}

def check(action, target, day):
    if ROE["halted"]:
        return "STOP: engagement halted by control group"
    start, end = ROE["window"]
    if not start <= day <= end:
        return "STOP: outside the agreed window"
    if target in ROE["off_limits"]:
        return "STOP: target is off limits"
    if action in ROE["prohibited"]:
        return "STOP: activity prohibited by the ROE"
    return "allowed: log it with time, operator and target"

print(check("ad_enumeration", "dc-02", "2026-11-10"))
print(check("simulated_exfil_1gb", "payroll-db-01", "2026-11-12"))
print(check("delete_user_data", "fs-04", "2026-11-12"))
ROE["halted"] = True
print(check("ad_enumeration", "dc-02", "2026-11-13"))

